<script setup>
import {computed,nextTick,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {action,money} from '../lib/ui'
import Icon from '../components/Icon.vue'
const auth=useAuthStore(),market=useMarketStore(),route=useRoute(),router=useRouter()
const active=ref(''),text=ref(''),busy=ref(false),chatBox=ref(null)
const key=c=>`${c.partnerId}|${c.productId}`
const conversations=computed(()=>{const list=market.conversations(auth.user.id);const {partner,product}=route.query;if(partner&&product&&partner!==auth.user.id&&market.profiles[partner]&&market.product(product)&&!list.some(c=>c.partnerId===partner&&c.productId===product))list.unshift({partnerId:String(partner),partnerName:market.profiles[partner].displayName,productId:String(product),lastMessage:'向同学打个招呼吧',updatedAt:new Date().toISOString(),unread:0});return list})
const current=computed(()=>conversations.value.find(c=>key(c)===active.value)||conversations.value[0]),product=computed(()=>market.product(current.value?.productId)),thread=computed(()=>current.value?market.thread(auth.user.id,current.value.partnerId,current.value.productId):[])
watch(()=>route.query,()=>{if(route.query.partner&&route.query.product)active.value=`${route.query.partner}|${route.query.product}`},{immediate:true})
async function scrollAndRead(){await nextTick();if(chatBox.value)chatBox.value.scrollTop=chatBox.value.scrollHeight;if(current.value)await market.markRead(auth.user.id,current.value.partnerId,current.value.productId)}
watch(()=>`${active.value}:${thread.value.length}`,()=>action(scrollAndRead),{flush:'post'})
onMounted(()=>action(scrollAndRead))
function choose(conversation){active.value=key(conversation);text.value='';router.replace({path:'/messages',query:{partner:conversation.partnerId,product:conversation.productId}});action(scrollAndRead)}
async function send(){if(!text.value.trim()||!current.value)return;busy.value=true;const result=await action(()=>market.sendMessage(auth.user,current.value.partnerId,current.value.productId,text.value));busy.value=false;if(result){text.value='';await scrollAndRead()}}
function time(value){return new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
</script>
<template><div class="page-width inner-page"><div class="page-title compact-title"><span class="eyebrow">SAY HELLO, PASS IT ON</span><h1>从一句“你好”开始。</h1><p>聊聊物品，也约一次轻松的校园交接。</p></div><div class="panel messages-layout"><aside class="conversation-list"><div class="conversation-heading"><h3>我的消息</h3><span>{{conversations.length}} 段相遇</span></div><button v-for="conversation in conversations" :key="key(conversation)" :class="['conversation-item',{active:key(current||{})===key(conversation)}]" @click="choose(conversation)"><span class="avatar">{{conversation.partnerName.slice(-2)}}</span><div><strong>{{conversation.partnerName}}</strong><small>{{conversation.lastMessage}}</small></div><b v-if="conversation.unread">{{conversation.unread}}</b></button><div v-if="!conversations.length" class="conversation-empty"><Icon name="message" :size="30"/><p>还没有消息<br>遇到喜欢的闲置就聊聊吧。</p></div><div class="conversation-footnote"><Icon name="shield" :size="16"/>只在校园里，放心聊一聊。</div></aside><section v-if="current" class="chat-panel"><header class="chat-header"><span class="avatar small">{{current.partnerName.slice(-2)}}</span><div><strong>{{current.partnerName}}</strong><small>{{market.profiles[current.partnerId]?.college}}</small></div><span><span class="status-dot"></span>校园同学</span></header><RouterLink v-if="product" :to="`/product/${product.id}`" class="chat-product"><img :src="product.images[0]" :alt="product.title"/><div><strong>{{product.title}}</strong><small>关于这件好物的对话</small></div><strong class="rose">¥{{money(product.price)}}</strong><Icon name="chevron" :size="17"/></RouterLink><div ref="chatBox" class="chat-messages"><div class="chat-day"><span>每一次真诚沟通，都让相遇更近一点。</span></div><div v-if="!thread.length" class="chat-starter"><Icon name="leaf" :size="38"/><h3>给这次相遇，写个开头。</h3><p>问问物品的情况，或约个熟悉的交接地点。</p></div><div v-for="message in thread" :key="message.id" :class="['message-row',{mine:message.senderId===auth.user.id}]"><span class="avatar small">{{market.profiles[message.senderId]?.displayName?.slice(-2)}}</span><div><p class="message-bubble">{{message.text}}</p><small>{{time(message.createdAt)}} <span v-if="message.senderId===auth.user.id">· {{message.read?'已读':'已发送'}}</span></small></div></div></div><form class="chat-compose" @submit.prevent="send"><textarea v-model="text" maxlength="2000" placeholder="想问什么，就从这里开始…（Enter 发送，Shift + Enter 换行）" aria-label="聊天消息" @keydown.enter.exact.prevent="send"/><div><span>友善沟通，保护个人信息。</span><button class="button primary" :disabled="busy||!text.trim()">发送<Icon name="send" :size="17"/></button></div></form></section><section v-else class="chat-panel empty-state"><Icon name="message" :size="48"/><h2>下一次相遇，正在路上。</h2><p>去逛逛市集，找一件心动的闲置。</p><RouterLink to="/market" class="button primary">去逛市集<Icon name="arrow" :size="17"/></RouterLink></section></div></div></template>
